// Package is retained from the application generated by the Tauri CLI.
__PACKAGE__

import android.os.Bundle
import android.os.Build
import android.view.View
import android.view.WindowManager
import androidx.activity.enableEdgeToEdge
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat

class MainActivity : TauriActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    enableEdgeToEdge()
    super.onCreate(savedInstanceState)
    val handlesKeyboardInsets = Build.VERSION.SDK_INT >= Build.VERSION_CODES.R
    window.setSoftInputMode(
      if (handlesKeyboardInsets) WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING
      else WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE
    )

    // Android 15+ enforces edge-to-edge. Inset the WebView's parent so its
    // entire viewport starts below status bars/cutouts, including on rotation.
    val content = findViewById<View>(android.R.id.content)
    ViewCompat.setOnApplyWindowInsetsListener(content) { view, insets ->
      val bars = insets.getInsets(
        WindowInsetsCompat.Type.systemBars() or WindowInsetsCompat.Type.displayCutout()
      )
      val keyboardBottom = if (handlesKeyboardInsets) {
        insets.getInsets(WindowInsetsCompat.Type.ime()).bottom
      } else 0
      view.setPadding(bars.left, bars.top, bars.right, maxOf(bars.bottom, keyboardBottom))
      // The native container already applies these insets. Don't apply them
      // a second time through the WebView's CSS safe-area environment values.
      WindowInsetsCompat.CONSUMED
    }
    ViewCompat.requestApplyInsets(content)
  }
}
